WITH matched_keys AS (SELECT store_id, id FROM store_sales EXCEPT DISTINCT SELECT store_id, id FROM store_sales WHERE store_id = 4), reconciled AS (SELECT s.* FROM store_sales s INNER JOIN matched_keys k ON s.store_id = k.store_id AND s.id = k.id) SELECT DATE_TRUNC('YEAR', sale_date) AS year_start, COUNT(DISTINCT store_id) AS distinct_store_ids, ROUND(AVG(units), 2) AS avg_units, STDDEV_SAMP(units) AS units_stddev, BIT_AND(units) AS units_bit_and, CORR(units, revenue) AS corr_units_revenue FROM reconciled GROUP BY DATE_TRUNC('YEAR', sale_date) ORDER BY avg_units NULLS LAST;
